-- Indexed scheduling metadata is a hint; projection and ledger guards still authorize work.
CREATE TABLE reconciliation_work (
 tenant TEXT NOT NULL, source TEXT NOT NULL, qso TEXT NOT NULL,
 revision TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1,
 priority TEXT NOT NULL CHECK(priority IN('live','background')),
 eligible INTEGER NOT NULL, context_ready INTEGER NOT NULL, context_expires_at INTEGER NOT NULL,
 next_due_at INTEGER NOT NULL DEFAULT 0, selected_at INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(tenant,source,qso), FOREIGN KEY(tenant,source) REFERENCES connections(tenant,id)
);
CREATE INDEX reconciliation_due ON reconciliation_work(tenant,source,priority,eligible,context_ready,next_due_at,selected_at,qso);
CREATE INDEX source_private_payload ON source_work(tenant,source,private_id);
CREATE TABLE reconciliation_checks (
 tenant TEXT NOT NULL, source TEXT NOT NULL, qso TEXT NOT NULL, destination TEXT NOT NULL,
 generation TEXT NOT NULL, checked_at INTEGER NOT NULL, next_due_at INTEGER NOT NULL,
 PRIMARY KEY(tenant,source,qso,destination)
);
CREATE TABLE reconciliation_policy (id TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO reconciliation_work(tenant,source,qso,revision,priority,eligible,context_ready,context_expires_at,selected_at) SELECT w.tenant,w.source,w.id,w.revision,CASE WHEN w.priority='live' OR EXISTS(SELECT 1 FROM source_births b WHERE b.tenant=w.tenant AND b.source=w.source AND b.qso=w.id AND b.phase='forward_new') OR EXISTS(SELECT 1 FROM ledger l WHERE l.tenant=w.tenant AND l.source=w.source AND l.qso=w.id AND l.state='changed') THEN 'live' ELSE 'background' END,w.state IN('pending','waiting'),CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END,CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation'),0) END,w.processed_at FROM source_work w WHERE w.kind='qso';
CREATE TRIGGER reconciliation_source_insert AFTER INSERT ON source_work WHEN NEW.kind='qso' BEGIN
 INSERT INTO reconciliation_work(tenant,source,qso,revision,priority,eligible,context_ready,context_expires_at,selected_at) VALUES(NEW.tenant,NEW.source,NEW.id,NEW.revision,CASE WHEN NEW.priority='live' OR EXISTS(SELECT 1 FROM source_births b WHERE b.tenant=NEW.tenant AND b.source=NEW.source AND b.qso=NEW.id AND b.phase='forward_new') OR EXISTS(SELECT 1 FROM ledger l WHERE l.tenant=NEW.tenant AND l.source=NEW.source AND l.qso=NEW.id AND l.state='changed') THEN 'live' ELSE 'background' END,NEW.state IN('pending','waiting'),CASE WHEN NEW.deleted=1 OR NEW.is_event=1 OR NEW.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=NEW.tenant AND o.source=NEW.source AND o.id=NEW.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END,CASE WHEN NEW.deleted=1 OR NEW.is_event=1 OR NEW.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=NEW.tenant AND o.source=NEW.source AND o.id=NEW.operation_id AND o.kind='operation'),0) END,NEW.processed_at);
END;
CREATE TRIGGER reconciliation_source_update AFTER UPDATE ON source_work WHEN NEW.kind='qso' BEGIN
 UPDATE reconciliation_work SET revision=NEW.revision,priority=CASE WHEN NEW.priority='live' OR EXISTS(SELECT 1 FROM source_births b WHERE b.tenant=NEW.tenant AND b.source=NEW.source AND b.qso=NEW.id AND b.phase='forward_new') OR EXISTS(SELECT 1 FROM ledger l WHERE l.tenant=NEW.tenant AND l.source=NEW.source AND l.qso=NEW.id AND l.state='changed') THEN 'live' ELSE 'background' END,eligible=NEW.state IN('pending','waiting'),context_ready=CASE WHEN NEW.deleted=1 OR NEW.is_event=1 OR NEW.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=NEW.tenant AND o.source=NEW.source AND o.id=NEW.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END,context_expires_at=CASE WHEN NEW.deleted=1 OR NEW.is_event=1 OR NEW.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=NEW.tenant AND o.source=NEW.source AND o.id=NEW.operation_id AND o.kind='operation'),0) END,selected_at=NEW.processed_at,version=version+CASE WHEN (NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.deleted IS NOT OLD.deleted OR NEW.is_event IS NOT OLD.is_event OR (NEW.state='pending' AND OLD.state!='pending')) THEN 1 ELSE 0 END,next_due_at=CASE WHEN (NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.deleted IS NOT OLD.deleted OR NEW.is_event IS NOT OLD.is_event OR (NEW.state='pending' AND OLD.state!='pending')) THEN 0 ELSE next_due_at END WHERE tenant=NEW.tenant AND source=NEW.source AND qso=NEW.id;
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND source=NEW.source AND qso=NEW.id AND (NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.operation_id IS NOT OLD.operation_id OR NEW.deleted IS NOT OLD.deleted OR NEW.is_event IS NOT OLD.is_event OR (NEW.state='pending' AND OLD.state!='pending'));
END;
CREATE TRIGGER reconciliation_source_delete AFTER DELETE ON source_work WHEN OLD.kind='qso' BEGIN
 DELETE FROM reconciliation_work WHERE tenant=OLD.tenant AND source=OLD.source AND qso=OLD.id;
 DELETE FROM reconciliation_checks WHERE tenant=OLD.tenant AND source=OLD.source AND qso=OLD.id;
END;
CREATE TRIGGER reconciliation_operation_insert AFTER INSERT ON source_work WHEN NEW.kind='operation' BEGIN
 UPDATE reconciliation_work SET context_ready=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),context_expires_at=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation'),0) END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),next_due_at=CASE WHEN 1 THEN 0 ELSE next_due_at END,version=version+CASE WHEN 1 THEN 1 ELSE 0 END WHERE tenant=NEW.tenant AND source=NEW.source AND qso IN(SELECT id FROM source_work WHERE tenant=NEW.tenant AND source=NEW.source AND operation_id=NEW.id AND kind='qso');
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND source=NEW.source AND 1 AND qso IN(SELECT id FROM source_work WHERE tenant=NEW.tenant AND source=NEW.source AND operation_id=NEW.id AND kind='qso');
END;
CREATE TRIGGER reconciliation_operation_update AFTER UPDATE ON source_work WHEN NEW.kind='operation' AND (NEW.state IS NOT OLD.state OR NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.deleted IS NOT OLD.deleted OR NEW.expires_at IS NOT OLD.expires_at) BEGIN
 UPDATE reconciliation_work SET context_ready=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),context_expires_at=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation'),0) END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),next_due_at=CASE WHEN (NEW.state IS NOT OLD.state OR NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.deleted IS NOT OLD.deleted OR (OLD.expires_at<=CAST(unixepoch('subsec')*1000 AS INTEGER) AND NEW.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER))) THEN 0 ELSE next_due_at END,version=version+CASE WHEN (NEW.state IS NOT OLD.state OR NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.deleted IS NOT OLD.deleted OR (OLD.expires_at<=CAST(unixepoch('subsec')*1000 AS INTEGER) AND NEW.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER))) THEN 1 ELSE 0 END WHERE tenant=NEW.tenant AND source=NEW.source AND qso IN(SELECT id FROM source_work WHERE tenant=NEW.tenant AND source=NEW.source AND operation_id=NEW.id AND kind='qso');
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND source=NEW.source AND (NEW.state IS NOT OLD.state OR NEW.revision IS NOT OLD.revision OR NEW.private_id IS NOT OLD.private_id OR NEW.deleted IS NOT OLD.deleted OR (OLD.expires_at<=CAST(unixepoch('subsec')*1000 AS INTEGER) AND NEW.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER))) AND qso IN(SELECT id FROM source_work WHERE tenant=NEW.tenant AND source=NEW.source AND operation_id=NEW.id AND kind='qso');
END;
CREATE TRIGGER reconciliation_context_body_insert AFTER INSERT ON private_data WHEN NEW.kind='source' BEGIN
 UPDATE reconciliation_work SET context_ready=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),context_expires_at=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation'),0) END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),next_due_at=CASE WHEN 1 THEN 0 ELSE next_due_at END,version=version+CASE WHEN 1 THEN 1 ELSE 0 END WHERE tenant=NEW.tenant AND source=NEW.connection AND qso IN(SELECT q.id FROM source_work o JOIN source_work q ON q.tenant=o.tenant AND q.source=o.source AND q.operation_id=o.id AND q.kind='qso' WHERE o.tenant=NEW.tenant AND o.source=NEW.connection AND o.private_id=NEW.id AND o.kind='operation');
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND source=NEW.connection AND 1 AND qso IN(SELECT q.id FROM source_work o JOIN source_work q ON q.tenant=o.tenant AND q.source=o.source AND q.operation_id=o.id AND q.kind='qso' WHERE o.tenant=NEW.tenant AND o.source=NEW.connection AND o.private_id=NEW.id AND o.kind='operation');
END;
CREATE TRIGGER reconciliation_context_body_update AFTER UPDATE ON private_data WHEN NEW.kind='source' AND (NEW.revoked_at IS NOT OLD.revoked_at OR NEW.expires_at IS NOT OLD.expires_at) BEGIN
 UPDATE reconciliation_work SET context_ready=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),context_expires_at=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation'),0) END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),next_due_at=CASE WHEN (NEW.revoked_at IS NOT OLD.revoked_at OR (OLD.expires_at IS NOT NULL AND OLD.expires_at<=CAST(unixepoch('subsec')*1000 AS INTEGER) AND (NEW.expires_at IS NULL OR NEW.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER)))) THEN 0 ELSE next_due_at END,version=version+CASE WHEN (NEW.revoked_at IS NOT OLD.revoked_at OR (OLD.expires_at IS NOT NULL AND OLD.expires_at<=CAST(unixepoch('subsec')*1000 AS INTEGER) AND (NEW.expires_at IS NULL OR NEW.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER)))) THEN 1 ELSE 0 END WHERE tenant=NEW.tenant AND source=NEW.connection AND qso IN(SELECT q.id FROM source_work o JOIN source_work q ON q.tenant=o.tenant AND q.source=o.source AND q.operation_id=o.id AND q.kind='qso' WHERE o.tenant=NEW.tenant AND o.source=NEW.connection AND o.private_id=NEW.id AND o.kind='operation');
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND source=NEW.connection AND (NEW.revoked_at IS NOT OLD.revoked_at OR (OLD.expires_at IS NOT NULL AND OLD.expires_at<=CAST(unixepoch('subsec')*1000 AS INTEGER) AND (NEW.expires_at IS NULL OR NEW.expires_at>CAST(unixepoch('subsec')*1000 AS INTEGER)))) AND qso IN(SELECT q.id FROM source_work o JOIN source_work q ON q.tenant=o.tenant AND q.source=o.source AND q.operation_id=o.id AND q.kind='qso' WHERE o.tenant=NEW.tenant AND o.source=NEW.connection AND o.private_id=NEW.id AND o.kind='operation');
END;
CREATE TRIGGER reconciliation_context_body_delete AFTER DELETE ON private_data WHEN OLD.kind='source' BEGIN
 UPDATE reconciliation_work SET context_ready=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 1 WHEN EXISTS(SELECT 1 FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation' AND o.state='context' AND o.deleted=0 AND p.revoked_at IS NULL) THEN 1 ELSE 0 END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),context_expires_at=(SELECT CASE WHEN w.deleted=1 OR w.is_event=1 OR w.operation_id IS NULL THEN 8640000000000000 ELSE COALESCE((SELECT MIN(o.expires_at,COALESCE(p.expires_at,8640000000000000)) FROM source_work o JOIN private_data p ON p.tenant=o.tenant AND p.connection=o.source AND p.id=o.private_id AND p.kind='source' WHERE o.tenant=w.tenant AND o.source=w.source AND o.id=w.operation_id AND o.kind='operation'),0) END FROM source_work w WHERE w.tenant=reconciliation_work.tenant AND w.source=reconciliation_work.source AND w.id=reconciliation_work.qso AND w.kind='qso'),next_due_at=CASE WHEN 1 THEN 0 ELSE next_due_at END,version=version+CASE WHEN 1 THEN 1 ELSE 0 END WHERE tenant=OLD.tenant AND source=OLD.connection AND qso IN(SELECT q.id FROM source_work o JOIN source_work q ON q.tenant=o.tenant AND q.source=o.source AND q.operation_id=o.id AND q.kind='qso' WHERE o.tenant=OLD.tenant AND o.source=OLD.connection AND o.private_id=OLD.id AND o.kind='operation');
 DELETE FROM reconciliation_checks WHERE tenant=OLD.tenant AND source=OLD.connection AND 1 AND qso IN(SELECT q.id FROM source_work o JOIN source_work q ON q.tenant=o.tenant AND q.source=o.source AND q.operation_id=o.id AND q.kind='qso' WHERE o.tenant=OLD.tenant AND o.source=OLD.connection AND o.private_id=OLD.id AND o.kind='operation');
END;
CREATE TRIGGER reconciliation_birth_insert AFTER INSERT ON source_births WHEN NEW.phase='forward_new' BEGIN
 UPDATE reconciliation_work SET priority='live',next_due_at=0 WHERE tenant=NEW.tenant AND source=NEW.source AND qso=NEW.qso;
END;
CREATE TRIGGER reconciliation_ledger_priority AFTER UPDATE OF state ON ledger WHEN NEW.state IS NOT OLD.state BEGIN
 UPDATE reconciliation_work SET priority=CASE WHEN NEW.state='changed' OR EXISTS(SELECT 1 FROM source_work w WHERE w.tenant=NEW.tenant AND w.source=NEW.source AND w.id=NEW.qso AND w.kind='qso' AND w.priority='live') OR EXISTS(SELECT 1 FROM source_births b WHERE b.tenant=NEW.tenant AND b.source=NEW.source AND b.qso=NEW.qso AND b.phase='forward_new') OR EXISTS(SELECT 1 FROM ledger l WHERE l.tenant=NEW.tenant AND l.source=NEW.source AND l.qso=NEW.qso AND l.state='changed') THEN 'live' ELSE 'background' END,next_due_at=CASE WHEN NEW.state='changed' THEN 0 ELSE next_due_at END WHERE tenant=NEW.tenant AND source=NEW.source AND qso=NEW.qso;
END;
CREATE TRIGGER reconciliation_connection_insert AFTER INSERT ON connections WHEN NEW.kind!='lofi' BEGIN
 UPDATE reconciliation_work SET next_due_at=0,version=version+1 WHERE tenant=NEW.tenant;
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND destination=NEW.id;
END;
CREATE TRIGGER reconciliation_connection_update AFTER UPDATE ON connections WHEN NEW.status IS NOT OLD.status OR NEW.credential_version IS NOT OLD.credential_version OR NEW.remote_identity IS NOT OLD.remote_identity OR (NEW.kind!='lofi' AND (json_extract(NEW.config,'$.stationCallsign') IS NOT json_extract(OLD.config,'$.stationCallsign') OR json_extract(NEW.config,'$.startDate') IS NOT json_extract(OLD.config,'$.startDate') OR json_extract(NEW.config,'$.endDate') IS NOT json_extract(OLD.config,'$.endDate') OR json_extract(NEW.config,'$.stations') IS NOT json_extract(OLD.config,'$.stations') OR json_extract(NEW.config,'$.station') IS NOT json_extract(OLD.config,'$.station') OR json_extract(NEW.config,'$.readAccess') IS NOT json_extract(OLD.config,'$.readAccess'))) BEGIN
 UPDATE reconciliation_work SET next_due_at=0,version=version+1 WHERE tenant=NEW.tenant AND (NEW.kind!='lofi' OR source=NEW.id);
 DELETE FROM reconciliation_checks WHERE tenant=NEW.tenant AND (NEW.kind='lofi' AND source=NEW.id OR NEW.kind!='lofi' AND destination=NEW.id);
END;
CREATE TRIGGER reconciliation_policy_insert AFTER INSERT ON reconciliation_policy BEGIN
 UPDATE reconciliation_work SET next_due_at=0,version=version+1;
 DELETE FROM reconciliation_checks;
END;
CREATE TRIGGER reconciliation_policy_update AFTER UPDATE ON reconciliation_policy WHEN NEW.value IS NOT OLD.value BEGIN
 UPDATE reconciliation_work SET next_due_at=0,version=version+1;
 DELETE FROM reconciliation_checks;
END;
